// ============================================================
// Build Airtable filter: next_follow_up <= today AND stage is active
// ============================================================
const today = new Date().toISOString().split('T')[0];
const formula = `AND(IS_BEFORE({next_follow_up}, '${today}T23:59:59.000Z'), OR({stage}='New', {stage}='Contacted', {stage}='Meeting Scheduled', {stage}='Proposal Sent', {stage}='Negotiating'))`;
const encoded = encodeURIComponent(formula);
return [{ json: { filter_url: `https://api.airtable.com/v0/appvFxwZc9yU8o8pK/Leads?filterByFormula=${encoded}&pageSize=100` } }];

// Check if there are leads to follow up on — with error handling
const response = $input.first().json;

// Handle Airtable fetch errors
if (response.error || response.statusCode >= 400 || !response.records) {
  return [{ json: { has_leads: false, count: 0, leads: [], _fetchError: response.error || response.statusMessage || 'Airtable fetch failed' } }];
}

const records = response.records || [];
if (records.length === 0) {
  return [{ json: { has_leads: false, count: 0, leads: [] } }];
}

const leads = records.map(r => ({
  record_id: r.id,
  company_name: r.fields.company_name || '',
  contact_name: r.fields.contact_name || '',
  email: r.fields.email || '',
  phone: r.fields.phone || '',
  industry: r.fields.industry || '',
  monthly_ad_spend: r.fields.monthly_ad_spend || '',
  stage: r.fields.stage || '',
  notes: r.fields.notes || '',
  next_follow_up: r.fields.next_follow_up || '',
  source: r.fields.source || '',
  website: r.fields.website || '',
  instagram: r.fields.instagram || '',
  linkedin: r.fields.linkedin || ''
}));

return [{ json: { has_leads: true, count: leads.length, leads } }];

// ============================================================
// Build Gemini prompt for all follow-up leads at once
// ============================================================
const data = $input.first().json;
const leads = data.leads;

const leadSummaries = leads.map((l, i) => {
  return `LEAD ${i + 1}:\n- Company: ${l.company_name}\n- Contact: ${l.contact_name}\n- Industry: ${l.industry || 'Unknown'}\n- Stage: ${l.stage}\n- Monthly Ad Spend: ${l.monthly_ad_spend || 'Unknown'}\n- Source: ${l.source || 'Unknown'}\n- Notes: ${l.notes || 'None'}\n- Last Follow-up Date: ${l.next_follow_up}\n- Website: ${l.website || 'N/A'}\n- Instagram: ${l.instagram || 'N/A'}`;
}).join('\n\n');

const systemPrompt = `You are the sales assistant for Smashed Agency — a UGC (user-generated content) and AI creatives agency based in India. We manage ~10 active clients, offering UGC script writing, AI-generated ad creatives, and full-service media buying (Meta + Google Ads).

Our core offerings:
- UGC Scripts: Hook-driven scripts for Instagram Reels, YouTube Shorts, and TikTok
- AI Creatives: AI-generated ad images and video variants
- Media Buying: Full campaign management on Meta and Google
- Strategy: Monthly content calendars, competitor analysis, performance optimization

Your job is to generate personalized, warm follow-up messages for each lead. The tone should be professional but approachable — like a knowledgeable friend in the industry, not a pushy salesperson. Reference specific details about their company, industry, or previous conversations when available.

For each lead, output a JSON object with:
- lead_index (number, 0-based)
- subject (short subject line for reference)
- message (the actual follow-up message, 3-5 sentences, ready to send via WhatsApp/email)
- channel ("whatsapp" if phone exists, "email" if only email, "linkedin" if only linkedin)
- urgency ("high" if overdue by 3+ days, "medium" if 1-2 days, "low" if today)

Return a JSON array of these objects. Only valid JSON, no markdown.`;

const userPrompt = `Today is ${new Date().toISOString().split('T')[0]}. Generate personalized follow-up messages for these ${leads.length} leads:\n\n${leadSummaries}`;

const geminiBody = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { temperature: 0.3, maxOutputTokens: 4000 }
};

return [{ json: { gemini_body: geminiBody, leads } }];

// Parse Gemini response with validation and fallback
const geminiResponse = $input.first().json;
const leads = $('Build Follow-up Prompt').first().json.leads;

// Validate Gemini response
let rawText = '';
const hasError = geminiResponse.error || geminiResponse.statusCode >= 400 || !geminiResponse.candidates;

if (!hasError) {
  try {
    rawText = geminiResponse.candidates[0].content.parts[0].text || '';
  } catch (e) {
    rawText = '';
  }
}

// If Gemini failed, generate basic follow-up reminders
if (!rawText) {
  const today = new Date();
  const results = leads.map((lead, idx) => {
    const overdueDays = lead.next_follow_up ? Math.floor((today - new Date(lead.next_follow_up)) / 86400000) : 0;
    const urgency = overdueDays >= 3 ? 'high' : overdueDays >= 1 ? 'medium' : 'low';
    const channel = lead.phone ? 'whatsapp' : lead.email ? 'email' : 'linkedin';
    return {
      record_id: lead.record_id,
      company_name: lead.company_name,
      contact_name: lead.contact_name,
      email: lead.email,
      phone: lead.phone,
      stage: lead.stage,
      subject: 'Follow-up: ' + lead.company_name,
      message: 'Hi ' + lead.contact_name + ', following up regarding ' + lead.company_name + '. We discussed our UGC and creative services — would love to continue the conversation. Let me know a good time to connect this week.',
      channel: channel,
      urgency: urgency
    };
  });
  return results.map(r => ({ json: r }));
}

// Parse Gemini JSON response
let cleaned = rawText.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```json?\s*/, '').replace(/```\s*$/, '').trim();
}

let followUps;
try {
  followUps = JSON.parse(cleaned);
} catch (e) {
  // JSON parse failed — generate basic reminders
  const results = leads.map(lead => ({
    record_id: lead.record_id,
    company_name: lead.company_name,
    contact_name: lead.contact_name,
    email: lead.email,
    phone: lead.phone,
    stage: lead.stage,
    subject: 'Follow-up: ' + lead.company_name,
    message: 'Hi ' + lead.contact_name + ', checking in regarding our conversation about UGC services for ' + lead.company_name + '. Happy to answer any questions or schedule a quick call.',
    channel: lead.phone ? 'whatsapp' : lead.email ? 'email' : 'linkedin',
    urgency: 'medium'
  }));
  return results.map(r => ({ json: r }));
}

if (!Array.isArray(followUps)) {
  followUps = [followUps];
}

const results = followUps.map(fu => {
  const idx = fu.lead_index || 0;
  const lead = leads[idx] || leads[0] || {};
  return {
    record_id: lead.record_id,
    company_name: lead.company_name,
    contact_name: lead.contact_name,
    email: lead.email,
    phone: lead.phone,
    stage: lead.stage,
    subject: fu.subject || '',
    message: fu.message || '',
    channel: fu.channel || 'email',
    urgency: fu.urgency || 'medium'
  };
});

return results.map(r => ({ json: r }));

// ============================================================
// Extract and validate proposal request
// ============================================================
const body = $input.first().json.body || $input.first().json;

const lead_id = (body.lead_id || '').trim();
const services = body.services || [];
const notes = (body.notes || '').trim();

if (!lead_id) throw new Error('lead_id is required');
if (!Array.isArray(services) || services.length === 0) {
  throw new Error('services array is required (e.g. ["ugc_scripts", "ai_creatives", "media_buying"])');
}

return [{ json: { lead_id, services, notes } }];

// Build URL for similar projects — with lead fetch error detection
const leadRecord = $input.first().json;
const reqData = $('Extract Proposal Request').first().json;

// Detect Airtable fetch failure
if (!leadRecord.id || leadRecord.error || leadRecord.statusCode >= 400) {
  return [{ json: {
    _error: true,
    errorMessage: leadRecord.error || leadRecord.statusMessage || 'Lead not found or Airtable fetch failed',
    lead_id: reqData.lead_id,
    services: reqData.services
  } }];
}

const f = leadRecord.fields || {};
const industry = f.industry || '';

let filterUrl = 'https://api.airtable.com/v0/appvFxwZc9yU8o8pK/Projects?pageSize=5&sort%5B0%5D%5Bfield%5D=created_at&sort%5B0%5D%5Bdirection%5D=desc';
if (industry) {
  const formula = encodeURIComponent("{industry}='" + industry + "'");
  filterUrl += '&filterByFormula=' + formula;
}

return [{ json: {
  _error: false,
  lead_record: leadRecord,
  lead_fields: f,
  services: reqData.services,
  proposal_notes: reqData.notes,
  projects_url: filterUrl
} }];

// ============================================================
// Build Gemini prompt for proposal generation
// ============================================================
const prevData = $('Prepare Projects Fetch').first().json;
if (prevData._error) {
  return [{ json: { ...prevData } }];
}
const lead = prevData.lead_fields;
const services = prevData.services;
const proposalNotes = prevData.proposal_notes;
const leadRecord = prevData.lead_record;

// Parse similar projects for context
const projectRecords = $input.first().json.records || [];
const projectContext = projectRecords.map(p => {
  const pf = p.fields || {};
  return `- ${pf.brand_name || 'Client'} (${pf.industry || 'N/A'}): ${pf.num_scripts || '?'} scripts, status: ${pf.status || 'N/A'}`;
}).join('\n');

const servicesDesc = services.map(s => {
  switch(s) {
    case 'ugc_scripts': return 'UGC Script Writing';
    case 'ai_creatives': return 'AI Ad Creatives';
    case 'media_buying': return 'Meta & Google Ads Media Buying';
    case 'strategy': return 'Content Strategy & Monthly Calendar';
    case 'competitor_analysis': return 'Competitor Ad Analysis';
    default: return s;
  }
}).join(', ');

const systemPrompt = `You are the proposal generator for Smashed Agency — a UGC and AI creatives agency based in India. We work with D2C brands, fintech companies, edtech platforms, and e-commerce businesses. We currently manage ~10 active clients.

Our pricing structure (in INR):

STARTER TIER (for brands spending < ₹2L/month on ads):
- 5 UGC Scripts/month: ₹15,000 - ₹25,000
- Includes: Hook research, script writing, 1 round of revisions
- Turnaround: 5-7 business days

GROWTH TIER (for brands spending ₹2L-10L/month):
- 10 UGC Scripts + AI Creatives: ₹30,000 - ₹50,000
- Includes: Deep competitor analysis, hook research, script writing, AI-generated ad images/videos, 2 rounds of revisions
- Turnaround: 7-10 business days

FULL-SERVICE TIER (for brands spending ₹10L+/month):
- 15+ UGC Scripts + AI Creatives + Media Buying: ₹75,000+
- Includes: Everything in Growth + full Meta/Google campaign management, weekly performance reports, monthly strategy calls, unlimited revisions
- Turnaround: Ongoing monthly retainer

ADD-ONS:
- Competitor Ad Analysis Report: ₹5,000 one-time
- Monthly Content Calendar: ₹8,000/month
- Additional script batches (5 scripts): ₹12,000

Generate a professional, personalized proposal. The proposal should:
1. Open with a brief understanding of their business and challenges
2. Recommend the appropriate tier based on their ad spend
3. Break down the selected services with deliverables and pricing
4. Include a clear timeline
5. End with next steps and a soft CTA

Format the proposal in clean text with clear sections (use ** for bold headers). Include specific numbers and deliverables — no vague promises. Reference their industry and any available context about their business.

Output ONLY the proposal text. No JSON wrapping. No markdown code fences.`;

const userPrompt = `Generate a proposal for this lead:

Company: ${lead.company_name || 'N/A'}
Contact: ${lead.contact_name || 'N/A'}
Industry: ${lead.industry || 'N/A'}
Website: ${lead.website || 'N/A'}
Instagram: ${lead.instagram || 'N/A'}
Monthly Ad Spend: ${lead.monthly_ad_spend || 'Not disclosed'}
Current Stage: ${lead.stage || 'N/A'}
Previous Notes: ${lead.notes || 'None'}

Requested Services: ${servicesDesc}
Additional Notes from Sales: ${proposalNotes || 'None'}

${projectContext ? 'Similar past projects for reference:\n' + projectContext : 'No similar past projects found.'}`;

const geminiBody = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { temperature: 0.3, maxOutputTokens: 3000 }
};

return [{ json: {
  gemini_body: geminiBody,
  lead_id: leadRecord.id,
  lead_fields: lead,
  services: services,
  services_desc: servicesDesc
} }];

// Parse proposal with Gemini validation
const geminiResponse = $input.first().json;
const prevData = $('Build Proposal Prompt').first().json;

// Propagate upstream errors
if (prevData._error) {
  return [{ json: { _error: true, errorMessage: prevData.errorMessage, lead_id: prevData.lead_id } }];
}

// Validate Gemini response
const hasError = geminiResponse.error || geminiResponse.statusCode >= 400 || !geminiResponse.candidates;
let proposalText = '';

if (!hasError) {
  try {
    proposalText = geminiResponse.candidates[0].content.parts[0].text || '';
  } catch (e) {
    proposalText = '';
  }
}

if (!proposalText) {
  return [{ json: {
    _error: true,
    errorMessage: 'Gemini failed to generate proposal: ' + (geminiResponse.error || geminiResponse.statusMessage || 'no content returned'),
    lead_id: prevData.lead_id,
    lead_fields: prevData.lead_fields,
    services_desc: prevData.services_desc
  } }];
}

// Clean up code fences
proposalText = proposalText.trim();
if (proposalText.startsWith('```')) {
  proposalText = proposalText.replace(/^```[a-z]*\s*/, '').replace(/```\s*$/, '').trim();
}

return [{ json: {
  _error: false,
  lead_id: prevData.lead_id,
  lead_fields: prevData.lead_fields,
  services: prevData.services,
  services_desc: prevData.services_desc,
  proposal_text: proposalText
} }];

// ============================================================
// Build Airtable PATCH to store proposal and update stage
// ============================================================
const data = $input.first().json;

const fields = {
  notes: data.proposal_text,
  stage: 'Proposal Sent'
};

return [{ json: {
  update_url: `https://api.airtable.com/v0/appvFxwZc9yU8o8pK/Leads/${data.lead_id}`,
  update_body: { fields },
  lead_id: data.lead_id,
  lead_fields: data.lead_fields,
  services_desc: data.services_desc,
  proposal_text: data.proposal_text
} }];

// ============================================================
// Prepare Slack notification for proposal
// ============================================================
const prevData = $('Build Proposal Update').first().json;
const lead = prevData.lead_fields;

// Truncate proposal for Slack (first 500 chars)
const proposalPreview = prevData.proposal_text.length > 500
  ? prevData.proposal_text.substring(0, 500) + '...'
  : prevData.proposal_text;

return [{ json: {
  lead_id: prevData.lead_id,
  company_name: lead.company_name || 'Unknown',
  contact_name: lead.contact_name || 'Unknown',
  services_desc: prevData.services_desc,
  proposal_preview: proposalPreview
} }];

