// ============================================================
const lead = $input.first().json;
const nextDate = new Date();
nextDate.setDate(nextDate.getDate() + 3);
const next_follow_up = nextDate.toISOString().split('T')[0];

return [{ json: {
  update_url: `https://api.airtable.com/v0/appvFxwZc9yU8o8pK/Leads/${lead.record_id}`,
  update_body: { fields: { next_follow_up } },
  record_id: lead.record_id,
  company_name: lead.company_name
} }];

// ============================================================
// Parse and validate incoming lead data
// ============================================================
const body = $input.first().json.body || $input.first().json;

function clean(val) {
  if (val === undefined || val === null) return '';
  if (Array.isArray(val)) return val.join(', ');
  return String(val).trim();
}

const company_name = clean(body.company_name || body.companyName || body.company);
const contact_name = clean(body.contact_name || body.contactName || body.name);
const email = clean(body.email);
const phone = clean(body.phone);
const instagram = clean(body.instagram);
const linkedin = clean(body.linkedin);
const website = clean(body.website);
const industry = clean(body.industry);
const monthly_ad_spend = clean(body.monthly_ad_spend || body.monthlyAdSpend || body.ad_spend);
const source = clean(body.source);
const notes = clean(body.notes);
const estimated_value = clean(body.estimated_value || body.estimatedValue);

if (!company_name) throw new Error('company_name is required');
if (!contact_name) throw new Error('contact_name is required');

// Set next_follow_up to 2 days from now by default
const followUp = new Date();
followUp.setDate(followUp.getDate() + 2);
const next_follow_up = body.next_follow_up || followUp.toISOString().split('T')[0];

return [{ json: {
  company_name,
  contact_name,
  email,
  phone,
  instagram,
  linkedin,
  website,
  industry,
  monthly_ad_spend,
  source,
  notes,
  estimated_value,
  next_follow_up,
  stage: 'New',
  created_at: new Date().toISOString().split('T')[0]
} }];

// ============================================================
// Build Airtable create payload — validate select fields against allowed values
