const fields = {};

// Allowed select field values (must match Airtable table schema exactly)
const VALID_SOURCES = ['Referral', 'Instagram', 'LinkedIn', 'Website', 'Cold Outreach'];
const VALID_STAGES = ['New', 'Contacted', 'Meeting Scheduled', 'Proposal Sent', 'Negotiating', 'Won', 'Lost'];

// Always set these
fields.company_name = lead.company_name;
fields.contact_name = lead.contact_name;

// Validate stage — must be a known select option
const stage = lead.stage || 'New';
if (VALID_STAGES.includes(stage)) {
  fields.stage = stage;
} else {
  fields.stage = 'New'; // Default to 'New' for unknown stages
}

// Only set created_at if it's a valid date-only format
if (lead.created_at) {
  const dateOnly = String(lead.created_at).split('T')[0];
  if (/^\d{4}-\d{2}-\d{2}$/.test(dateOnly)) {
    fields.created_at = dateOnly;
  }
}

// Only set non-empty optional fields
if (lead.email) fields.email = lead.email;
if (lead.phone) fields.phone = lead.phone;
if (lead.instagram) fields.instagram = lead.instagram;
if (lead.linkedin) fields.linkedin = lead.linkedin;
if (lead.website) fields.website = lead.website;
if (lead.industry) fields.industry = lead.industry;
if (lead.monthly_ad_spend) {
  const spend = Number(String(lead.monthly_ad_spend).replace(/[^0-9.]/g, ''));
  if (!isNaN(spend) && spend > 0) fields.monthly_ad_spend = spend;
}

// Validate source — must be a known select option (omit if unknown)
if (lead.source) {
  const src = String(lead.source).trim();
  if (VALID_SOURCES.includes(src)) {
    fields.source = src;
  }
  // If source doesn't match, omit it rather than crash
}

if (lead.notes) fields.notes = lead.notes;
if (lead.estimated_value) {
  const num = Number(String(lead.estimated_value).replace(/[^0-9.]/g, ''));
  if (!isNaN(num) && num > 0) fields.estimated_value = num;
}
if (lead.next_follow_up) {
  const dateOnly = String(lead.next_follow_up).split('T')[0];
  if (/^\d{4}-\d{2}-\d{2}$/.test(dateOnly)) {
    fields.next_follow_up = dateOnly;
  }
}

return [{ json: { fields, lead } }];

// Prepare Slack notification for new lead — with error detection
const record = $input.first().json;
const f = record.fields || {};
const lead = $('Build Lead Payload').first().json.lead;

// Detect Airtable create failure
if (!record.id || record.error || record.statusCode >= 400) {
  return [{ json: {
    _error: true,
    errorMessage: record.error || record.statusMessage || 'Failed to create lead in Airtable (no record ID returned)',
    company_name: lead.company_name,
    contact_name: lead.contact_name
  } }];
}

return [{ json: {
  _error: false,
  record_id: record.id,
  company_name: f.company_name || lead.company_name,
  contact_name: f.contact_name || lead.contact_name,
  email: f.email || lead.email || 'N/A',
  phone: f.phone || lead.phone || 'N/A',
  industry: f.industry || lead.industry || 'N/A',
  source: f.source || lead.source || 'N/A',
  monthly_ad_spend: f.monthly_ad_spend || lead.monthly_ad_spend || 'N/A',
  estimated_value: f.estimated_value || lead.estimated_value || 'N/A',
  next_follow_up: f.next_follow_up || lead.next_follow_up || 'N/A',
  notes: f.notes || lead.notes || ''
} }];

